CREATE FUNCTION "nightscout_migration_namespace"."allocate_tenant_insertion_ordinal"() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $tenant_insertion$
BEGIN
  IF NEW.tenant_id IS DISTINCT FROM NULLIF(current_setting('app.current_tenant_id',true),'')::uuid THEN
    RAISE EXCEPTION 'TENANT_ORDINAL_BINDING_REQUIRED';
  END IF;
  IF TG_OP='UPDATE' THEN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.insertion_ordinal IS DISTINCT FROM OLD.insertion_ordinal THEN
      RAISE EXCEPTION 'TENANT_ORDINAL_IMMUTABLE';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "nightscout_migration_namespace"."tenant_insertion_ordinal" WHERE tenant_id=NEW.tenant_id)
     AND EXISTS (SELECT 1 FROM "nightscout_migration_namespace"."devicestatus" WHERE tenant_id=NEW.tenant_id) THEN
    RAISE EXCEPTION 'TENANT_ORDINAL_COUNTER_MISSING';
  END IF;
  IF NEW.insertion_ordinal IS NULL THEN
    INSERT INTO "nightscout_migration_namespace"."tenant_insertion_ordinal" AS counter (tenant_id,last_ordinal) VALUES (NEW.tenant_id,1)
      ON CONFLICT (tenant_id) DO UPDATE SET last_ordinal=counter.last_ordinal+1
      WHERE counter.last_ordinal<9223372036854775807
      RETURNING counter.last_ordinal INTO NEW.insertion_ordinal;
    IF NOT FOUND THEN RAISE EXCEPTION 'TENANT_ORDINAL_EXHAUSTED' USING ERRCODE='22003'; END IF;
  ELSE
    IF NEW.insertion_ordinal<=0 THEN RAISE EXCEPTION 'TENANT_ORDINAL_INVALID'; END IF;
    INSERT INTO "nightscout_migration_namespace"."tenant_insertion_ordinal" AS counter (tenant_id,last_ordinal) VALUES (NEW.tenant_id,NEW.insertion_ordinal)
      ON CONFLICT (tenant_id) DO UPDATE SET last_ordinal=GREATEST(counter.last_ordinal,EXCLUDED.last_ordinal);
  END IF;
  RETURN NEW;
END
$tenant_insertion$

